# Keep the packaged payload byte-identical to the canonical authorized source.
# The preceding literal is retained only for readable source history; runtime and
# the Windows bundle use this compressed canonical payload.
_SOURCE_JSON = zlib.decompress(b64decode("")).decode("utf-8")


def source_bytes() -> bytes:
    """The exact, byte-identical metadata catalogue built into Windows EXE."""
    return _SOURCE_JSON.encode("utf-8")


def professional_genres() -> tuple[dict, ...]:
    data = json.loads(source_bytes())
    if (type(data) is not dict
        or data.get("schema") != "accessible-chess-38-39-master-libraries-by-genre-v1"
        or data.get("languages") != ["uk", "en"]
        or type(data.get("genres")) is not list
        or len(data["genres"]) != 25
        or data.get("contains_book_binary") is not False):
        raise ValueError("packaged professional chess catalogue schema invalid")
    identities = set()
    for item in data["genres"]:
        ident = item.get("id")
        if (type(ident) is not str or not ident.isascii()
            or not ident.replace("_", "").isalnum() or ident in identities
            or type(item.get("uk")) is not str or len(item["uk"]) < 5
            or type(item.get("en")) is not str or len(item["en"]) < 5
            or type(item.get("professional_book_references")) is not list
            or type(item.get("original_or_derived_source_candidates")) is not list
            or item.get("full_genre_qualification_obtained") is not False
            or item.get("no_beginners") is not True):
            raise ValueError("unsupported professional genre record")
        identities.add(ident)
    return tuple(data["genres"])


def build_professional_genre_book(*, language: str = "uk") -> BookDocument:
    if type(language) is not str or language not in {"uk", "en"}:
        raise ValueError("professional catalogue language must be uk/en")
    english = language == "en"
    blocks = [
        Heading(
            text=("Advanced chess literature and database genres — candidate master to GM"
                  if english else
                  "Професійна шахова література й бази — від КМС до GM"),
            level=1, block_id="advanced-genres-heading",
            source_anchor="section38:master:heading",
        ),
        Paragraph(
            text=(
                "This is a professional bibliography and source status map. It "
                "contains no full third-party book texts. The real imported "
                "exercises are 16 Lichess 2200+ and four 3000+ PUZZLES (not FIDE "
                "Elo or player titles). Source names do not prove usable external "
                "files or final format qualification."
                if english else
                "Це професійна бібліографія і карта джерел, а НЕ повні тексти "
                "захищених авторським правом видань. Реальні вправи програми: "
                "16 задач Lichess 2200+ та чотири 3000+ (складність задач, "
                "не FIDE Elo й не звання шахіста). Згадка про формат чи джерело "
                "не означає, що його файл завантажено або імпорт підтверджено."
            ),
            block_id="advanced-genres-intro",
            source_anchor="section38:master:intro",
        ),
    ]
    for index, genre in enumerate(professional_genres(), 1):
        ident = genre["id"]
        blocks.append(Heading(
            text=f"{index}. {genre[language]}",
            level=2, block_id="advanced-genre-" + ident,
            source_anchor="section38:master:genre:" + ident,
        ))
        candidates = genre["original_or_derived_source_candidates"]
        source_line = "; ".join(
            x["catalog_source_id"] + " [" + x["qualification_status"] + "]"
            for x in candidates
        )
        blocks.append(Paragraph(
            text=(
                "Source candidates, not confirmed full original books: "
                if english else
                "Потенційні джерела, а не підтверджені повні оригінальні книги: "
            ) + source_line,
            source_anchor="section38:master:genre:" + ident + ":sources",
        ))
        bibliography = genre["professional_book_references"]
        if bibliography:
            citations = "; ".join(
                x["author"] + " — " + x["title"] + " (" + x["provider_url"] + ")"
                for x in bibliography
            )
            blocks.append(Paragraph(
                text=(
                    "Publisher references only; editions/licenses have not been "
                    "authenticated for redistribution: "
                    if english else
                    "Тільки бібліографія видавця; права на копіювання видань "
                    "не підтверджені: "
                ) + citations,
                source_anchor="section38:master:genre:" + ident + ":references",
            ))
        blocks.append(Paragraph(
            text=(
                "Full original format/annotation and Windows NVDA acceptance: "
                "NOT VERIFIED for this complete genre."
                if english else
                "Повне приймання оригіналів усіх форматів, анотацій і Windows NVDA "
                "для цього жанру: НЕ ПІДТВЕРДЖЕНО."
            ),
            source_anchor="section38:master:genre:" + ident + ":status",
        ))
    book = BookDocument(
        title=(
            "Professional chess study: 25 literature and database genres (UK/EN)"
            if english else "Професійні шахи: 25 жанрів літератури та баз (УКР/EN)"
        ),
        author="Accessible Chess — originally authored QA bibliographic index",
        language=language,
        source_name="Section38-39 original bilingual QA genre registry",
        source_rights=(
            "Own bibliographic descriptions and facts; original external publishers "
            "retain all rights; no paid book content was reproduced."
        ),
        blocks=blocks,
    )
    book.as_dict()
    return book


